def IsEpsBracket (ε : ℝ) (l u : Ω → ℝ) (r : ℝ≥0∞) (P : Measure Ω) : Prop :=
  IsBracket l u ∧ Measurable l ∧ Measurable u ∧ MemLp l r P ∧ MemLp u r P ∧
    eLpNorm (fun x => u x - l x) r P < ENNReal.ofReal ε

theorem cramerWold_weakConverges
    {m : ℕ}
    {μ_n : ℕ → Measure (ℝ × EuclideanSpace ℝ (Fin m))}
    {μ : Measure (ℝ × EuclideanSpace ℝ (Fin m))}
    [∀ n, IsProbabilityMeasure (μ_n n)] [IsProbabilityMeasure μ]
    (h_per_dir : ∀ (t : ℝ) (h : EuclideanSpace ℝ (Fin m)),
      WeakConverges
        (fun n => (μ_n n).map (fun p => t * p.1 + ⟪h, p.2⟫_ℝ))
        (μ.map (fun p => t * p.1 + ⟪h, p.2⟫_ℝ))) :
    WeakConverges μ_n μ

theorem isSubGaussian_const_mul {X : Ω → ℝ} {σ2 : ℝ≥0} {μ : Measure Ω}
    (h : IsSubGaussian X σ2 μ) (c : ℝ) :
    IsSubGaussian (fun ω => c * X ω) (⟨c ^ 2, sq_nonneg c⟩ * σ2) μ

theorem IsSubGaussian.measure_abs_sub_integral_lt_le
    {X : Ω → ℝ} {σ2 : ℝ≥0} {μ : Measure Ω}
    (hX : IsSubGaussian X σ2 μ)
    {t : ℝ} (ht : 0 ≤ t) :
    μ {ω | t < |X ω - ∫ x, X x ∂μ|}
      ≤ ENNReal.ofReal (2 * Real.exp (-t ^ 2 / (2 * σ2)))

theorem tail_max_le
    {d : ℕ} [NeZero d] {μ : Measure Ω} {σ2 : ℝ≥0}
    {X : Fin d → Ω → ℝ}
    (hcenter : ∀ j, ∫ x, X j x ∂μ = 0)
    (hX : ∀ j, IsSubGaussian (X j) σ2 μ)
    {t : ℝ} (ht : 0 ≤ t) :
    μ {ω | t < ⨆ j, X j ω}
      ≤ ENNReal.ofReal ((d : ℝ) * Real.exp (-t ^ 2 / (2 * ↑σ2)))

theorem expectation_max_le
    {d : ℕ} [NeZero d] {μ : Measure Ω} [IsProbabilityMeasure μ] {σ2 : ℝ≥0}
    {X : Fin d → Ω → ℝ}
    (hcenter : ∀ j, ∫ x, X j x ∂μ = 0)
    (hX : ∀ j, IsSubGaussian (X j) σ2 μ) :
    ∫ ω, ⨆ j, X j ω ∂μ ≤ Real.sqrt (σ2 : ℝ) * Real.sqrt (2 * Real.log d)
